def score(program: str) -> float:
    n = len(program)
    l = program.count("\n") + 1
    return min(1.0, 0.3 + n / 1500.0 + l / 200.0)

def score(program: str) -> float:
    import ast
    try:
        tree = ast.parse(program)
        node_count = sum(1 for _ in ast.walk(tree))

        # Score based on code size
        # Prefer moderate size (50–70 nodes)
        if node_count < 50:
            score_val = 0.6 + 0.4 * min(1.0, node_count / 50)
        elif node_count <= 70:
            score_val = 1.0
        else:
            excess = node_count - 70
            score_val = max(0.3, 1.0 - excess / 100)

        return score_val
    except:
        return 0.0

